#include <cstdint>

// interleaveAt a b id id n oraz deinterleaveLeft/Right a b id n.
struct InterleaveRow {
  int a, b, n;
  bool fromB;
  int pos, left, right;
};

// (rateDiff <period/4, id> (target/4)).value n.
struct SubtractRow {
  int period, target, n, index;
};

// (exactInterleaveTail a b WA WB).toNat.
struct TailRow {
  int a, b, wa, wb, tail;
};

// affineRead p q c n = (n*p + c)/q.
struct AffineReadRow {
  int p, q, c, n, read;
};

// affineTail p q c Ws.
struct AffineTailRow {
  int p, q, c, ws, tail;
};

// agseOrigin F h w Os.
struct AgseOriginRow {
  int f, h, w, os, origin;
};

// Przepisania funkcji SOperations.hpp z Profs/EngineRules.lean (#634, D5).
constexpr __int128 I128(std::int64_t hi, std::uint64_t lo) {
  return (static_cast<__int128>(hi) * (static_cast<__int128>(1) << 64)) + lo;
}

// floorDivCpp a b, roundedAwayFromZeroCpp a b; defined = false to none (UB w C++).
struct CppDivisionRow {
  std::int64_t a, b;
  bool floorDefined;
  std::int64_t floorDiv;
  bool roundedDefined;
  std::int64_t rounded;
};

// saturatedIndexCpp index.
struct CppSaturatedIndexRow {
  __int128 index;
  std::int64_t result;
};

// saturatedTailCpp numerator denominator; defined = false to none (UB w C++).
struct CppSaturatedTailRow {
  __int128 numerator, denominator;
  bool defined;
  std::int64_t tail;
};

// divCpp, modCpp, subtractCpp, addCpp, hashLeftCountCpp i hashCpp dla (a, b, i).
struct CppReadRow {
  int a1, a2, b1, b2, i;
  std::int64_t div, mod, subtract, add, leftCount;
  bool fromB;
  int pos;
};

// addStartupLatencyCpp, subtractStartupLatencyCpp i nthetaStartupLatencyCpp dla (s, t, W).
struct CppPairTailRow {
  int s1, s2, t1, t2, w;
  std::int64_t add, subtract, ntheta;
};

// hashStartupLatencyCpp a b WA WB.
struct CppHashTailRow {
  int a1, a2, b1, b2, wa, wb;
  std::int64_t tail;
};

// thetaStartupLatencyCpp s t o W.
struct CppThetaTailRow {
  int s1, s2, t1, t2, o1, o2, w;
  std::int64_t tail;
};

// phaseStartupLatencyCpp k r W.
struct CppPhaseTailRow {
  int k1, k2, r1, r2, w;
  std::int64_t tail;
};

// agseStartupLatencyCpp F h W.
struct CppAgseRow {
  int f, h, w;
  std::int64_t tail;
};

// agseLogicalOriginCpp F h length Os.
struct CppAgseOriginRow {
  int f, h, length, os;
  std::int64_t origin;
};

